inline TVector<T> TQuat<T>::UnrotateVector(TVector<T> V) const
{	
	const TVector<T> Q(-X, -Y, -Z); // Inverse
	const TVector<T> TT = 2.f * TVector<T>::CrossProduct(Q, V);
	const TVector<T> Result = V + (W * TT) + TVector<T>::CrossProduct(Q, TT);
	return Result;
}

[[nodiscard]] TVector<T> operator/(FArg Scale) const
{
	const T RScale = T(1) / Scale;
	return TVector<T>(X * RScale, Y * RScale, Z * RScale);
}

template<typename T>
inline bool TVector<T>::Normalize(T Tolerance)
{
    const T SquareSum = X*X + Y*Y + Z*Z;
    if(SquareSum > Tolerance)
    {
        const T Scale = FMath::InvSqrt(SquareSum);
        X *= Scale; Y *= Scale; Z *= Scale;
        return true;
    }
    return false;

#[must_use]
pub fn inverse(self) -> Self {
    glam_assert!(self.is_normalized());
    self.conjugate()
}

/// # Panics
///
/// Will panic if `self` is not normalized when `glam_assert` is enabled.
#[inline]
#[must_use]
pub fn mul_vec3(self, rhs: Vec3) -> Vec3 {
    glam_assert!(self.is_normalized());

    self.mul_vec3a(rhs.into()).into()
}

pub fn mul_vec3a(self, rhs: Vec3A) -> Vec3A {
    unsafe {
        let w = self.w;
        let b = Vec3A::from(self.0);
        let b2 = b.length_squared();
        Vec3A(vaddq_f32(
            vaddq_f32(
                vmulq_n_f32(rhs.0, (w * w) - b2),
                vmulq_n_f32(b.0, rhs.dot(b) * 2.0),
            ),
            vmulq_n_f32(b.cross(rhs).0, w * 2.0),
        ))
    }

